import {captureDragActors} from './drag-actors.mjs';
import * as T from './vendor/three.module.js';
import {makePerson,animatePerson} from './town-life/people/models.mjs';
import {population} from './town-life/people/core.mjs';
import {ACTOR_TYPES,SIMULATION_LIMITS} from './actor-catalog.mjs';
import {hash,affinityColor} from './world-model.mjs';
function actorModel(type,id){if(['rabbit','wolf'].includes(type))return simpleActor(type);const spec=ACTOR_TYPES[type],people=population(hash(id),'alder'),p=structuredClone(people.find(p=>type==='broom-elder'?p.role==='resident':p.role==='delivery'));p.id=id;p.wardrobe.accessory='none';p.wardrobe.hat='none';p.wardrobe.top=spec.color;if(type==='zombie'){p.appearance.skin='#8eaa77';p.appearance.hair='#414837';p.wardrobe.bottom='#505344';}if(type==='broom-elder'){p.appearance.hair='#d6d2cb';p.wardrobe.top=['#977c9b','#7c8a9e','#a28a68'][hash(id)%3];}const model=makePerson(p);model.userData.inertiaLayer='people';if(type==='wizard')model.add(wizardHat());return model;}
function broom(){const g=new T.Group(),wood=new T.MeshLambertMaterial({color:'#886a43'}),straw=new T.MeshLambertMaterial({color:'#c5ad6c'}),handle=new T.Mesh(new T.CylinderGeometry(.025,.025,1.25,6),wood);handle.position.y=.1;g.add(handle);const head=new T.Mesh(new T.BoxGeometry(.38,.3,.12),straw);head.position.y=-.58;g.add(head);g.position.set(.25,.68,.08);g.rotation.z=-.15;return g;}
export function attachOutbreakPreview(group,assembly,spec,scale){const root=new T.Group();root.scale.setScalar(scale);const points=assembly.plans.flatMap(p=>p.paths.flatMap(path=>path.points.map(v=>({x:p.center.x+v.x,z:p.center.z+v.z}))));for(let i=0;i<spec.count;i++){const point=points[(i*13+7)%points.length]||{x:0,z:0},model=actorModel(spec.archetype,'preview'+i);if(spec.archetype==='broom-elder')model.add(broom());model.position.set(point.x,.1,point.z);root.add(model);}group.add(root);}
export function createOutbreakView(scene,scale){const root=new T.Group();root.scale.setScalar(scale);scene.add(root);const records=new Map();let last=performance.now();const crowd=createCrowdView(scene,scale),effects=createEffectsView(scene,scale);let crowded=false;
 function draw(w,heightAt,{visible=true,admin=false,colorKind=''}={}){root.visible=visible;if(!w?.actors)return;const active=Object.values(w.actors).filter(a=>w.entities[a.id]?.active&&a.hp>0);crowded=active.length>SIMULATION_LIMITS.detailActors;effects.draw(w,visible);crowd.draw(w,heightAt,{visible:visible&&crowded,colorKind:admin?colorKind:'',admin});if(crowded){root.visible=false;return;}const now=performance.now(),dt=Math.min(.1,(now-last)/1000);last=now;
 for(const [id,view]of records)if(!w.entities[id]?.active){root.remove(view.wrapper);view.sprite.material.map.dispose();view.sprite.material.dispose();view.ring.geometry.dispose();view.ring.material.dispose();records.delete(id);}
 for(const a of Object.values(w.actors)){if(!w.entities[a.id]?.active)continue;let v=records.get(a.id);
  if(!v){const wrapper=new T.Group(),model=actorModel(a.archetype,a.id),canvas=document.createElement('canvas');canvas.width=384;canvas.height=96;const texture=new T.CanvasTexture(canvas),sprite=new T.Sprite(new T.SpriteMaterial({map:texture,depthTest:false}));sprite.scale.set(6.8,1.7,1);sprite.position.y=3.2;const ring=new T.Mesh(new T.RingGeometry(.6,.85,20),new T.MeshBasicMaterial({side:T.DoubleSide,transparent:true,opacity:.85,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.y=.08;wrapper.add(model,sprite,ring);wrapper.position.set(a.position.x,heightAt(a.position.x,a.position.z),a.position.z);wrapper.userData.worldEntityId=a.id;root.add(wrapper);v={wrapper,model,sprite,canvas,ring,weapon:null,status:'',position:{...a.position}};records.set(a.id,v);}
  v.wrapper.visible=a.hp>0&&!v.wrapper.userData.dragHidden;if(a.hp<=0)continue;
  if(a.weapon==='broom'&&!v.weapon){v.weapon=broom();v.model.add(v.weapon);}if(a.weapon!=='broom'&&v.weapon){v.model.remove(v.weapon);v.weapon=null;}
  const old=v.wrapper.position.clone(),factor=1-Math.exp(-dt*15);v.wrapper.position.x+=(a.position.x-v.wrapper.position.x)*factor;v.wrapper.position.z+=(a.position.z-v.wrapper.position.z)*factor;v.wrapper.position.y=heightAt(v.wrapper.position.x,v.wrapper.position.z)+.05;
  const dx=v.wrapper.position.x-old.x,dz=v.wrapper.position.z-old.z,moved=Math.hypot(dx,dz);if(moved>.001)v.model.rotation.y=Math.atan2(dx,dz);if(v.model.userData.limbs)animatePerson(v.model,{text:a.intent==='attacking'?'Working':'Walking'},moved,dt,false);if(['attacking','casting'].includes(a.intent)){if(v.model.userData.limbs)v.model.userData.limbs[2].rotation.x=-1.3;if(v.weapon)v.weapon.rotation.x=-1.1;}else if(v.weapon)v.weapon.rotation.x=0;
  v.ring.visible=admin&&!!colorKind;if(v.ring.visible)v.ring.material.color.set(affinityColor(w,a.id,colorKind));v.sprite.visible=admin;const status=a.name+' · '+a.hp+'/'+a.maxHp+' HP\n'+a.intent+(a.burning?' · burning':'')+(a.weapon?' · '+a.weapon:' · unarmed');if(admin&&v.status!==status){v.status=status;const c=v.canvas.getContext('2d');c.clearRect(0,0,384,96);c.fillStyle='#11241ee8';c.fillRect(0,0,384,96);c.fillStyle='#fff8dc';c.font='bold 23px sans-serif';c.textAlign='center';c.fillText(status.split('\n')[0],192,28);c.font='19px sans-serif';c.fillText(status.split('\n')[1],192,55);c.fillStyle='#4b5c4b';c.fillRect(18,70,348,12);c.fillStyle=a.team==='undead'?'#a5c66d':'#75b7d2';c.fillRect(18,70,348*a.hp/a.maxHp,12);v.sprite.material.map.needsUpdate=true;}
 }
 }
 return {draw,captureDrag:options=>crowded?crowd.captureDrag(options):captureDragActors([...records.values()].map(v=>v.wrapper),{...options,scale})};
}
function wizardHat(){const g=new T.Group(),mat=new T.MeshLambertMaterial({color:'#514184'}),brim=new T.Mesh(new T.CylinderGeometry(.36,.36,.05,10),mat),cone=new T.Mesh(new T.ConeGeometry(.28,.65,10),mat);brim.position.y=1.65;cone.position.y=1.98;g.add(brim,cone);return g;}
function simpleActor(type){const spec=ACTOR_TYPES[type],g=new T.Group(),coat=new T.MeshLambertMaterial({color:spec.color}),skin=new T.MeshLambertMaterial({color:type==='zombie'?'#99ad72':'#e3c4a0'}),eye=new T.MeshLambertMaterial({color:'#302e2a'});
 const ellipsoid=(x,y,z,sx,sy,sz,material=coat)=>{const m=new T.Mesh(new T.SphereGeometry(1,8,5),material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);g.add(m);return m;};
 if(type==='rabbit'){ellipsoid(0,.23,0,.22,.23,.38);ellipsoid(0,.4,.25,.19,.2,.19);for(const x of [-.1,.1]){ellipsoid(x,.72,.22,.05,.27,.06);ellipsoid(x,.43,.4,.035,.035,.03,eye);}ellipsoid(0,.28,-.38,.13,.13,.13);}
 else if(type==='wolf'){ellipsoid(0,.55,0,.3,.32,.62);ellipsoid(0,.8,.48,.24,.24,.32);for(const x of [-.2,.2])for(const z of [-.38,.38])ellipsoid(x,.24,z,.08,.3,.1);for(const x of [-.16,.16]){const ear=new T.Mesh(new T.ConeGeometry(.1,.25,5),coat);ear.position.set(x,1,.48);g.add(ear);}ellipsoid(0,.6,-.7,.1,.12,.4);}
 else {ellipsoid(0,.78,0,.28,.55,.19);ellipsoid(0,1.48,0,.22,.24,.21,skin);for(const x of [-.13,.13])ellipsoid(x,.25,0,.085,.3,.09);if(type==='wizard')g.add(wizardHat());if(type==='broom-elder')g.add(broom());}
 g.userData.inertiaLayer='people';return g;
}
function createCrowdView(scene,scale){const root=new T.Group();root.scale.setScalar(scale);scene.add(root);const pools=new Map(),handles=new Map(),matrix=new T.Matrix4(),dummy=new T.Object3D(),color=new T.Color();
 function pool(type){if(pools.has(type))return pools.get(type);const template=simpleActor(type);template.updateMatrixWorld(true);const parts=[];template.traverse(o=>{if(!o.isMesh)return;const mesh=new T.InstancedMesh(o.geometry,o.material,SIMULATION_LIMITS.actors);mesh.frustumCulled=false;mesh.count=0;root.add(mesh);parts.push({mesh,local:o.matrixWorld.clone()});});pools.set(type,parts);return parts;}
 let healthBars=null;function draw(w,heightAt,{visible,colorKind,admin}){root.visible=visible;if(!visible)return;if(admin&&!healthBars){healthBars=new T.InstancedMesh(new T.BoxGeometry(1.3,.08,.18),new T.MeshBasicMaterial({color:'#87b65e'}),SIMULATION_LIMITS.actors);healthBars.frustumCulled=false;root.add(healthBars);}if(healthBars){healthBars.visible=admin;healthBars.count=0;}for(const parts of pools.values())for(const p of parts)p.mesh.count=0;const active=new Set();for(const a of Object.values(w.actors)){if(!w.entities[a.id]?.active||a.hp<=0)continue;active.add(a.id);let handle=handles.get(a.id);if(!handle){handle=new T.Group();handle.userData.worldEntityId=a.id;handle.userData.type=a.archetype;handles.set(a.id,handle);}handle.position.set(a.position.x,heightAt(a.position.x,a.position.z)+.05,a.position.z);handle.visible=!handle.userData.dragHidden;if(!handle.visible)continue;const parts=pool(a.archetype),index=parts[0].mesh.count;dummy.position.copy(handle.position);const next=a.route?.points[a.route.next];if(next)handle.rotation.y=Math.atan2(next.x-a.position.x,next.z-a.position.z);dummy.rotation.copy(handle.rotation);dummy.scale.set(1,1,1);dummy.updateMatrix();if(admin){dummy.position.y+=2.4;dummy.scale.x=a.hp/a.maxHp;dummy.updateMatrix();healthBars.setMatrixAt(healthBars.count++,dummy.matrix);dummy.position.copy(handle.position);dummy.scale.set(1,1,1);dummy.updateMatrix();}for(const p of parts){matrix.multiplyMatrices(dummy.matrix,p.local);p.mesh.setMatrixAt(index,matrix);if(colorKind)p.mesh.setColorAt(index,color.set(affinityColor(w,a.id,colorKind)));else if(p.mesh.instanceColor)p.mesh.setColorAt(index,color.set('#ffffff'));p.mesh.count++;}}
 if(healthBars)healthBars.instanceMatrix.needsUpdate=true;for(const [id]of handles)if(!active.has(id))handles.delete(id);for(const parts of pools.values())for(const p of parts){p.mesh.instanceMatrix.needsUpdate=true;if(p.mesh.instanceColor)p.mesh.instanceColor.needsUpdate=true;}}
 return {draw,captureDrag(options){for(const handle of handles.values())if(!handle.children.length)handle.add(simpleActor(handle.userData.type));const capture=captureDragActors([...handles.values()],{...options,scale});for(const handle of handles.values())handle.clear();return capture;}};
}
function createEffectsView(scene,scale){let root=null;const views=new Map(),geometry=new T.SphereGeometry(1,8,6),fire=new T.MeshBasicMaterial({color:'#ff8a36',transparent:true,opacity:.85}),ember=new T.MeshBasicMaterial({color:'#f4c044',transparent:true,opacity:.7});return {draw(w,visible){const items=[...(w.encounter?.projectiles||[]).map(p=>({id:'p'+p.id,position:p.position,radius:.35,material:fire})),...(w.encounter?.effects||[]).map((e,i)=>({id:'e'+i,position:e.position,radius:e.radius,material:ember})),...Object.values(w.actors).filter(a=>a.hp>0&&a.burning&&w.entities[a.id]?.active).map(a=>({id:'b'+a.id,position:{...a.position,y:a.position.y+.65},radius:.55,material:fire}))];if(!root&&items.length){root=new T.Group();root.scale.setScalar(scale);scene.add(root);}if(!root)return;root.visible=visible;const ids=new Set(items.map(x=>x.id));for(const [id,v]of views)if(!ids.has(id)){root.remove(v);views.delete(id);}for(const item of items){let v=views.get(item.id);if(!v){v=new T.Mesh(geometry,item.material);root.add(v);views.set(item.id,v);}v.position.set(item.position.x,item.position.y,item.position.z);v.scale.setScalar(item.radius);}}};}
